DOCKER="${DOCKER:-docker}"; AMD_SMI="${AMD_SMI:-amd-smi}"; CURL="${CURL:-curl}"; SS="${SS:-ss}"
# --- run-time knobs ---
ONLY="${ONLY:-}"                     # comma-separated cell-slug globs; empty = every non-smoke cell
