[ "$WATCH_S" -ge 1 ] || { echo "RUN REFUSED: WATCH_S must be >= 1" >&2; exit 1; }
FIRST_WARMUP=0 API=completions PREFIX_MODE=unique
ALL_CELLS=('iq5rs-d8000-n1' 'iq5rs-d32000-n1' 'iq5rs-d64000-n1' 'iq5rs-d80000-n1' 'iq5rs-d100000-n1' 'iq5rs-d200000-n1')
UNPINNED=()
if [ ! -f "$RES/meta.txt" ]; then
  { echo "date=$(date -Iseconds)"; echo "campaign=27b-iq5r-s-v4-speed-gate (multi-engine throughput, gen_campaign G1)"
    echo "order=iq5rs"
